{
 "paper_title": "TRIMMED k-MEANS: AN ATTEMPT TO ROBUSTIFY QUANTIZERS",
 "authors_year": "J. A. Cuesta-Albertos, A. Gordaliza and C. Matrán (1997)",
 "research_question": "How can k-means clustering be robustified against outliers using impartial trimming, and what are the existence, characterization, and strong consistency properties of such trimmed k-means?",
 "context": "Traditional k-means clustering and joint location M-estimators can be highly unstable and lack robustness in the presence of outliers or contamination. While trimming procedures are useful, standard techniques suffer from arbitrariness in selecting zones for data removal. Building on Gordaliza's impartial trimming concept, this paper extends trimming to robustify k-means and analyzes its theoretical consistency.",
 "methods": [
  "Formulation of impartial trimming functions and trimmed k-variation using penalty functions",
  "Mathematical proofs for the existence and characterization of trimmed k-means",
  "Proof of strong consistency of empirical trimmed k-means using the Skorohod representation theorem and continuity results",
  "Simulation studies on bivariate normal distributions with mixture contamination (outliers and inliers) to evaluate robustness and mean estimation bias",
  "Simulated annealing-based random optimization algorithm implemented in Matlab to handle the nonexistence of deterministic optimal algorithms"
 ],
 "main_findings": [
  "The optimal trimming function essentially coincides with the indicator function of a nonpathological set formed by the union of k balls of equal radius (Corollary 3.2)",
  "Trimmed k-means induces a partition of the optimal ball into k clusters, and each cluster center is a penalty-mean of X given that cluster (Proposition 3.3)",
  "Proof of existence of trimmed k-means under mild continuity and growth conditions on the penalty function (Theorem 3.1)",
  "Proof of strong consistency of trimmed k-means and trimmed k-variation under continuity of the limit probability distribution (Theorem 3.6)",
  "Simulations show the method successfully detects anomalies and estimates cluster means, though a bias appears at low trimming levels due to probability mass distribution on the boundary of trimming balls"
 ],
 "assumptions": [
  "The penalty function Phi is continuous, nondecreasing, with Phi(0)=0 and Phi(x) < infinity for all x",
  "The probability measure PX of the limit random vector is continuous",
  "The number of clusters k and the trimming level alpha are given and fixed"
 ],
 "limitations_explicit": [
  "There is no deterministic optimal algorithm to choose the optimal trimming set, requiring heuristic optimization such as simulated annealing (Sections 1 and 4)",
  "The theoretical breakdown point depends heavily on the data and can be low if the underlying distribution contains dense mass concentrations or contamination proportional to cluster weights (Section 5)",
  "All clusters obtained by the method are forced to be spherical and have the same radius (Corollary 3.2 and Section 4)"
 ],
 "potential_open_questions": [
  {
   "question": "How can the breakdown point of alpha-trimmed k-means be explicitly bounded or improved when clusters have unequal proportions or complex shapes?",
   "why_unresolved": "The breakdown point depends heavily on the data structure and underlying cluster probabilities rather than being universally robust across all configurations.",
   "evidence": "Section 5 discusses an example where the breakdown point of the alpha-trimmed k-means can be as close to 0 as desired depending on the configuration and data distribution.",
   "sections": [
    "Section 5"
   ]
  },
  {
   "question": "What are the exact asymptotic convergence rates and limiting distributions for empirical trimmed k-means estimators?",
   "why_unresolved": "While strong consistency is established, deriving the exact limiting distribution is complicated by discontinuities of the trimming functions on the boundaries of the balls.",
   "evidence": "Section 3 mentions that trimming functions are discontinuous on the boundary of corresponding balls, requiring careful handling of convergences without providing a full central limit theorem for trimmed k-means.",
   "sections": [
    "Section 3"
   ]
  }
 ],
 "candidate_hypotheses": [
  {
   "hypothesis": "If the penalty function Phi is continuously differentiable and strictly convex, then there is no probability mass at the boundary between clusters.",
   "rationale": "Smoothness and strict convexity eliminate boundary ambiguity in cluster assignments and partition geometry.",
   "evidence": "Section 3 cites previous work (Cuesta-Albertos, Gordaliza and Matrán, 1995) establishing this property under continuously differentiable, strictly convex penalty functions.",
   "sections": [
    "Section 3"
   ]
  },
  {
   "hypothesis": "For a probability Q supported by exactly k clusters with respective probabilities q_1, ..., q_k, the breakdown point of the alpha-trimmed k-mean is at most min(alpha, q_1, ..., q_k) independently of the penalty function.",
   "rationale": "Contamination exceeding the relative mass of individual natural clusters forces the estimator to capture anomalous points as valid clusters or trim valid data.",
   "evidence": "Section 5 analyzes the behavior of trimmed k-means under contaminated discrete uniform setups and deduces bounds on the breakdown behavior relative to cluster probabilities.",
   "sections": [
    "Section 5"
   ]
  }
 ]
}

{
 "paper_title":"Robust k-means: a Theoretical Revisit",
 "authors_year":"Alexandros Georgogiannis (2016)",
 "research_question":"What are the robustness and consistency properties of robust k-means (RKM) under arbitrary and well-structured datasets?",
 "context":"Clustering noisy data using robust variants of quadratic k-means, specifically focusing on regularization/penalized methods (robust k-means) and their relationship to trimmed k-means.",
 "methods":[
  "Theoretical analysis using variational analysis and Moreau envelopes",
  "Finite sample breakdown point analysis",
  "Vapnik-Chervonenkis theory for consistency properties",
  "Synthetic data experiments comparing RKM and trimmed k-means on Gaussian mixtures"
 ],
 "main_findings":[
  "Two outliers are enough to break down the cluster centers in robust k-means under general conditions.",
  "When datasets are well-structured (e.g., balanced with separated balls of inliers), robust k-means effectively ignores outliers.",
  "The universal breakdown point of robust k-means with unbiased proximal maps is 2/n.",
  "Non-asymptotic consistency results for standard quadratic k-means remain valid for the robust variant even when penalties are non-convex."
 ],
 "assumptions":[
  "Observations can be decomposed into an inlier part and an error/outlier term penalized by a group penalty.",
  "Proximal maps are either biased (convex penalties) or unbiased (non-convex penalties like l0-norm).",
  "Datasets in the restricted robustness analysis contain balanced clusters covered by balls of bounded radius that are sufficiently far apart."
 ],
 "limitations_explicit":[
  "Robust k-means cannot be robust against any arbitrary type of contamination and any type of dataset when general universal breakdown points are considered."
 ],
 "potential_open_questions":[
  {
   "question":"How can robust k-means formulations be extended to handle high-dimensional overlapping clusters effectively without strict separation assumptions?",
   "why_unresolved":"Current theoretical guarantees rely heavily on the assumption that inlier clusters are well-separated by a minimum distance v.",
   "evidence":"The analysis in Section 3.3 and Theorem 2 requires centers of the balls to be at least v apart.",
   "sections":[
    "3.3"
   ]
  }
 ],
 "candidate_hypotheses":[
  {
   "hypothesis":"Adaptive choice of the regularization parameter lambda can improve outlier rejection rates in multi-scale cluster densities.",
   "rationale":"Fixed global thresholds like lambda may either under-penalize heavy contamination or over-penalize tight inlier groups in complex mixtures.",
   "evidence":"Section 5 demonstrates that grid search for lambda is required to match performance under different contamination scenarios.",
   "sections":[
    "5"
   ]
  }
 ]
}

